function d_ddl_gen(P,R){var t=P.table||'records';var cols=(P.columns||[{n:'id',t:'TEXT PRIMARY KEY'}]).map(function(c){return '  '+c.n+' '+c.t;}).join(',\n');var sql='CREATE TABLE '+t+' (\n'+cols+'\n);';return{table:t,columns:P.columns.length,ddl:sql};}

// invoked with params:
// {"table":"records","columns":[{"n":"id","t":"TEXT PRIMARY KEY"},{"n":"title","t":"TEXT"},{"n":"body","t":"TEXT"}]}

output.ddl:
CREATE TABLE records (
  id TEXT PRIMARY KEY,
  title TEXT,
  body TEXT
);

